SELECT u.unit_id, u.unit_code, dn.blood_group, u.component, u.expires_on, row_number() OVER (PARTITION BY dn.blood_group, u.component ORDER BY u.expires_on ASC) AS fefo_priority FROM blood_unit u JOIN donation d ON d.donation_id = u.donation_id JOIN donor dn ON dn.donor_id = d.donor_id WHERE u.status = 'AVAILABLE' AND u.expires_on >= CURRENT_DATE ORDER BY dn.blood_group, u.component, fefo_priority;
